#[serde(deny_unknown_fields)]
struct Review {
    id: String,
    verdict: String,
    reason: Option<String>,
    proposed_precondition: Option<Value>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Reviews {
    reviews: Vec<Review>,
