    let target_ref = proposal_target(&candidate)?;
    let target =
        ubu_store::queries::get_current_state(state.inner().store.pool(), target_ref.id.as_str())
            .await?
            .ok_or_else(|| AppError::TargetNotFound {
                id: target_ref.id.to_string(),
            })?;
